// daemonset/cni-mtu-patch.yaml - Permanent Flannel / Calico MTU Fix
apiVersion: v1
kind: ConfigMap
metadata:
  name: cni-network-config
  namespace: kube-system
data:
  cni-conf.json: |
    {
      "name": "cbr0",
      "cniVersion": "0.3.1",
      "plugins": [
        {
          "type": "flannel",
          "delegate": {
            "hairpinMode": true,
            "isDefaultGateway": true,
            "mtu": 1450 # 1500 Physical MTU - 50 bytes VXLAN header overhead!
          }
        }
      ]
    }
---
# Host Level Immediate Sysctl Workaround (TCP MSS Clamping via iptables)
# sudo iptables -t mangle -A POSTROUTING -p tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
